                ['Quick buying checklist', '<ul><li>Choose material for weight, durability and heating needs.</li><li>Test whether the lid design looks easy to use and clean.</li><li>Measure cabinet and refrigerator space.</li><li>Check dishwasher, microwave, freezer and oven guidance.</li><li>Buy a set size that matches the portions you actually store.</li></ul>'],
            ],
        ],
    ];
}

require_once __DIR__ . '/guides-content-1.php';
require_once __DIR__ . '/guides-content-2.php';
require_once __DIR__ . '/guides-content-3.php';

function dd_guides_data()
{
    static $guides = null;
    if ($guides !== null) return $guides;

    $guides = dd_guides_data_base();
    $long = dd_guides_content_1() + dd_guides_content_2() + dd_guides_content_3();
    foreach ($guides as $slug => &$guide) {
        if (isset($long[$slug])) {
            $guide['sections'] = $long[$slug];
            $guide['updated'] = 'September 24, 2026';
        }
        $words = 0;
        foreach ($guide['sections'] as $section) {
            $words += str_word_count(strip_tags($section[0] . ' ' . $section[1]));
        }
        $guide['read_time'] = max(1, (int) ceil($words / 200)) . ' min read';
    }
    unset($guide);
    return $guides;
}

function dd_guide_by_slug($slug)
{
    $guides = dd_guides_data();
    return $guides[$slug] ?? null;
}
